CREATE TABLE IF NOT EXISTS market_documents (id text PRIMARY KEY, source_id text NOT NULL REFERENCES market_sources(source_id), run_id text NOT NULL REFERENCES market_source_runs(id), source_url text NOT NULL, published_at timestamptz, text text NOT NULL, raw_hash text NOT NULL, status text NOT NULL DEFAULT 'pending', extracted_count integer NOT NULL DEFAULT 0, receipt_id bigint, error text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_id,source_url,raw_hash));
